corporate_design.toad_component_blueprint:
canvas {
  size: 880px 600px;
  fill: #FAF8F5;
  font-family: "Cormorant Garamond, serif";
}

>gold = #D4AF37;
>black = #1C1917;

rect #boxFrame {
  at: center of canvas;
  size: 760px 480px;
  fill: #FFFFFF;
  stroke: >gold;
  stroke-width: 1px;
}

text #maisonTitle {
  at: top center of #boxFrame offset 0px 48px;
  content: "MAISON VELLUM • GRASSE";
  font-size: 15px;
  font-weight: 600;
  color: >gold;
}

text #fragranceTitle {
  at: below #maisonTitle offset 16px;
  content: "CUIR BLANC // EXTRAIT DE PARFUM";
  font-size: 32px;
  font-weight: 700;
  color: >black;
}
